<?php require 'config.php';login_required();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT r.*,u.name requester FROM requests r JOIN users u ON u.id=r.requester_id WHERE r.id=?");$s->execute([$id]);$r=$s->fetch();if(!$r)exit(current_lang()==='th'?'ไม่พบข้อมูล':'Record not found');$it=db()->prepare("SELECT ri.*,m.code,m.name,m.unit,m.price FROM request_items ri JOIN materials m ON m.id=ri.material_id WHERE ri.request_id=?");$it->execute([$id]);$items=$it->fetchAll();$ap=db()->prepare("SELECT a.*,u.name approver FROM approval_steps a LEFT JOIN users u ON u.id=a.approver_id WHERE a.request_id=? ORDER BY level_no");$ap->execute([$id]);$steps=$ap->fetchAll();$lg=db()->prepare("SELECT l.*,u.name FROM audit_logs l JOIN users u ON u.id=l.user_id WHERE l.request_id=? ORDER BY l.id DESC");$lg->execute([$id]);$logs=$lg->fetchAll();?><!doctype html><html lang="<?=e(current_lang())?>"><head><?php include 'partials/head.php';?></head><body><?php include 'partials/nav.php';?><main class="container"><div class="page-head"><div><h2><?=e(t('request_no'))?> <?=e($r['request_no'])?></h2><p><?=e(t('requester'))?>: <?=e($r['requester'])?> · <?=e(t('department'))?>: <?=e($r['department'])?></p></div><span class="badge <?=e($r['status'])?>"><?=e(status_text($r['status']))?></span></div><div class="panel"><b><?=e(t('purpose'))?>:</b><br><span class="muted"><?=nl2br(e($r['purpose']))?></span></div><div class="panel"><div class="panel-head"><h3><?=e(t('items'))?></h3></div><div class="table-wrap"><table class="table"><thead><tr><th><?=e(t('code'))?></th><th><?=e(t('material'))?></th><th><?=e(t('quantity'))?></th><th><?=e(t('unit'))?></th><th><?=e(t('price'))?></th><th><?=e(t('note'))?></th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['code'])?></td><td><?=e($x['name'])?></td><td><?=fmt_number($x['qty'])?></td><td><?=e($x['unit'])?></td><td><?=fmt_number($x['price'])?></td><td><?=e($x['note'])?></td></tr><?php endforeach;?></tbody></table></div></div><div class="panel"><div class="panel-head"><h3><?=e(t('approval_workflow'))?></h3><span>3-Level Workflow</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Level</th><th>Role</th><th><?=e(t('requester'))?></th><th><?=e(t('status'))?></th><th><?=e(t('comment'))?></th></tr></thead><tbody><?php foreach($steps as $x):?><tr><td><?=$x['level_no']?></td><td><?=e(role_text($x['role_code']))?></td><td><?=e($x['approver']??'-')?></td><td><span class="badge <?=e($x['status'])?>"><?=e(status_text($x['status']))?></span></td><td><?=e($x['comment'])?></td></tr><?php endforeach;?></tbody></table></div></div><div class="panel"><div class="panel-head"><h3><?=e(t('history'))?></h3></div><?php foreach($logs as $x):?><p class="small"><b><?=e($x['name'])?></b> · <?=e($x['action'])?> · <?=e($x['detail'])?> <span class="muted">— <?=e($x['created_at'])?></span></p><?php endforeach;?></div></main></div></div></body></html>
